from nlib import *
S=[]
SK="skeletal_system"
def B(id,title,sc,sm,basics,deeper,expert,facts,dyk,sec,mesh=None,par=(SK,),made=("bone_tissue",),extra=None,**kw):
    S.append(N(id,title,"organ" if sc>0.05 else "structure","anatomy",sc,sm,basics,deeper,expert,facts,dyk,par=par,made=made,mesh=mesh or id,refs=[("ANP",sec)],kn=["musculoskeletal"],rel=kw.pop("rel",[]),**kw))
B("skull","Skull",0.2,"The skull is the bony case of 22 fused and joined bones that houses the brain and shapes the face.","The skull protects your brain and holds your eyes, ears, nose and teeth. Most of its bones are locked together by zig-zag seams.","Eight cranial bones form the braincase and fourteen facial bones form the face; sutures are fibrous joints that allow growth in childhood. Holes (foramina) pass nerves and vessels, such as the foramen magnum for the spinal cord.","Cranial vault bones are intramembranous (dermal) while the base is largely endochondral. Sutures close variably in adulthood. Paranasal sinuses lighten the skull and the sphenoid, temporal and ethmoid bones form a complex skull base.",[("Bones","22 (8 cranial + 14 facial)"),("Foramen magnum","≈ 3.5 cm long"),("Adult skull mass","≈ 0.7-1 kg")],"A newborn's skull has soft gaps (fontanelles) so the head can squeeze through the birth canal.","7.2",rel=["brain"])
B("mandible","Mandible (jaw bone)",0.12,"The mandible is the only movable bone of the skull and holds the lower teeth.","Your lower jaw swings open and shut on hinge-like joints in front of the ears, letting you bite, chew and speak.","It articulates with the temporal bone at the temporomandibular joint. Chewing muscles (masseter, temporalis) attach to it.","The condylar process forms a synovial joint with a fibrocartilaginous disc that permits hinge and glide movement. The inferior alveolar nerve runs within the mandibular canal.",[("Teeth held","16 (adult lower)"),("Bite force (molars)","≈ 500-700 N")],"The mandible is the strongest and densest bone of the face.","7.2",par=(SK,"skull"))
B("cervical_spine","Cervical spine",0.12,"Seven neck vertebrae that carry the head and allow it to nod and turn.","The neck's seven small bones, C1 to C7, hold the head up. The top two, atlas and axis, are specially shaped so you can nod yes and shake no.","Each vertebra has a body, arch and processes and the stack encloses the spinal cord. Intervertebral discs cushion the joints, and transverse foramina carry the vertebral arteries.","Atlanto-occipital joint supports flexion-extension, atlanto-axial joint (dens of C2) supports ~50% of cervical rotation. Cervical lordosis is a secondary curve developing as infants lift their heads.",[("Vertebrae","7 (C1-C7)"),("Head mass carried","≈ 4.5-5 kg")],"Giraffes and humans both have exactly seven neck vertebrae.","7.3")
B("thoracic_spine","Thoracic spine",0.28,"Twelve mid-back vertebrae that anchor the ribs.","These 12 vertebrae each hold a pair of ribs, making the upper back more rigid but giving the chest its protective cage.","Facets on the vertebral bodies and transverse processes form joints with ribs. The thoracic spine has a gentle outward curve (kyphosis).","Rib articulations (costovertebral and costotransverse) limit motion; spinous processes slope downward and overlap. Disc height is smaller than in lumbar vertebrae.",[("Vertebrae","12 (T1-T12)"),("Length","≈ 28 cm")],"Thoracic vertebrae change shape gradually, with the lower ones looking more like lumbar vertebrae.","7.3")
B("lumbar_spine","Lumbar spine",0.18,"Five large lower-back vertebrae that bear most of the upper body's weight.","Your lower back has five thick vertebrae built to carry weight and bend. This area takes the strain when you lift.","Large vertebral bodies and thick discs support compressive load; the inward curve (lordosis) helps balance the trunk over the pelvis.","Lumbar discs transmit load via nucleus pulposus hydrostatics and annulus fibrosus collagen lamellae. Spinal cord ends near L1-L2 (conus medullaris); below is the cauda equina.",[("Vertebrae","5 (L1-L5)"),("Typical disc height","≈ 9-10 mm")],"The spinal cord ends higher than the spine does, so lumbar punctures are made below it where only nerve roots float.","7.3")
B("sacrum","Sacrum",0.12,"A wedge of five fused vertebrae that links the spine to the pelvis.","The sacrum is a triangle-shaped bone at the base of the spine that locks into the pelvis like a keystone.","It forms joints with the two hip bones (sacroiliac joints) and has holes through which sacral nerves pass.","Sacral fusion completes through the late teens to the twenties; the sacral promontory is an obstetric landmark. S2-S4 supply parasympathetic outflow to pelvic organs.",[("Fused vertebrae","5"),("Width","≈ 10-12 cm")],"The name 'sacrum' comes from Latin for 'sacred bone'.","7.3")
B("ribcage","Rib cage",0.3,"Twelve pairs of ribs enclose the heart and lungs and move during breathing.","Your ribs form a flexible cage around the heart and lungs. They swing up and out when you breathe in.","The first seven pairs attach to the sternum directly via costal cartilage, pairs 8 to 10 attach indirectly, and the last two are floating.","'Pump-handle' and 'bucket-handle' rib motions increase the anteroposterior and transverse diameters. Intercostal muscles stabilize and move the ribs.",[("Rib pairs","12"),("Longest rib","≈ 24 cm (7th-8th)")],"About 1 in 200 people has an extra (cervical) rib.","7.4")
B("sternum","Sternum",0.17,"The breastbone, a flat bone at the center of the chest.","The sternum is the flat bone in the middle of your chest that most of your ribs attach to.","It has three parts: the manubrium, body, and the xiphoid process. It protects the heart and holds bone marrow suitable for sampling.","The manubriosternal joint (sternal angle) is a landmark at the level of the 2nd rib and T4/T5, where the trachea bifurcates and the aortic arch begins/ends.",[("Length","≈ 17 cm"),("Parts","3")],"The sternal angle is used by doctors to count ribs.","7.4")
B("pelvis","Pelvis",0.3,"A bowl of bone formed by two hip bones, the sacrum and the coccyx.","The pelvis carries your upper-body weight to your legs and cradles the organs of the lower abdomen.","Each hip bone is made of three fused bones (ilium, ischium, pubis). The hip sockets (acetabula) hold the heads of the femurs.","Sex differences in pelvic inlet shape reflect obstetric adaptation; the pelvis is a compromise between bipedal locomotion and childbirth ('obstetric dilemma', debated).",[("Width","≈ 28-30 cm"),("Joints","2 sacroiliac + pubic symphysis")],"The pelvis' shape is among the best clues to a skeleton's sex.","8.3")
for sd,s2,sn in (("l","left","Left"),("r","right","Right")):
    B(f"clavicle_{sd}",f"{sn} clavicle (collarbone)",0.15,f"The {s2} collarbone braces the shoulder away from the chest.","A slender S-shaped bone that holds your shoulder out to the side and is the one most often broken in a fall.","It connects the sternum to the scapula and transmits forces from the arm to the trunk.","Intramembranous ossification begins here earliest, and it is the last to fuse its medial growth plate (around age 25).",[("Length","≈ 15 cm")],"It is one of the first bones to start ossifying in the embryo and one of the last to finish.","8.1",par=(SK,"shoulder_girdle_note") if False else (SK,))
    B(f"scapula_{sd}",f"{sn} scapula (shoulder blade)",0.15,f"The {s2} shoulder blade is a flat triangle sliding over the back of the ribs.","A flat bone on the upper back that forms the socket of the shoulder and anchors many muscles.","The glenoid cavity forms the shoulder socket; spine and acromion provide leverage for deltoid and trapezius.","Scapulothoracic motion contributes about one third of arm elevation (scapulohumeral rhythm ~2:1).",[("Width","≈ 10 cm"),("Length","≈ 15 cm")],"The scapula is connected to the trunk by muscles only, with no true joint to the ribs.","8.1")
    B(f"humerus_{sd}",f"{sn} humerus (upper arm bone)",0.32,f"The {s2} humerus is the long bone of the upper arm.","The bone between your shoulder and elbow; its rounded top fits into the shoulder socket.","The humeral head articulates with the scapula, and the distal end forms the elbow with the radius and ulna.","The radial nerve winds in the spiral groove of the shaft, so mid-shaft fractures may injure it.",[("Length","≈ 30-35 cm")],"The 'funny bone' is the ulnar nerve running behind the humerus, not a bone.","8.2",rel=["long_bone"])
    B(f"radius_ulna_{sd}",f"{sn} radius and ulna (forearm)",0.27,f"The {s2} forearm's two long bones allow the hand to rotate.","Two parallel bones between elbow and wrist. The radius crosses over the ulna when you turn your palm down.","The ulna forms the main elbow hinge; the radius forms the main wrist joint. An interosseous membrane links them.","Pronation-supination occurs at proximal and distal radioulnar joints with the radius rotating around a fixed ulna.",[("Length","≈ 24-28 cm")],"Your forearm can turn about 180 degrees.","8.2")
    B(f"hand_bones_{sd}",f"{sn} hand bones",0.19,f"The {s2} hand has 27 bones in wrist, palm and fingers.","Eight small wrist bones, five palm bones and fourteen finger bones give your hand fine control.","Opposable thumb saddle joint allows pinch and grip.","Carpal arrangement in two rows; scaphoid is the most commonly fractured carpal and has retrograde blood supply, risking avascular necrosis.",[("Bones","27"),("Share of body's bones","≈ 13%")],"Each hand holds roughly a quarter of all the body's bones.","8.2")
    B(f"femur_{sd}",f"{sn} femur (thigh bone)",0.45,f"The {s2} femur is the longest, strongest bone in the body.","The femur is your thigh bone. It must carry several times your body weight when you run or jump.","Its ball-shaped head fits the hip socket; the lower end forms the knee. The neck angle is about 125 degrees.","Trabecular architecture aligns with principal stress trajectories; femoral neck fractures are a major osteoporosis outcome.",[("Length","≈ 45 cm"),("Typical load while running","≈ 3-5× body weight")],"The femur's length is about a quarter of a person's height.","8.4",rel=["long_bone"])
    B(f"patella_{sd}",f"{sn} patella (kneecap)",0.05,f"The {s2} kneecap is a sesamoid bone in the quadriceps tendon.","A small bone in front of the knee that works as a pulley to boost the thigh muscle's pull.","It increases the lever arm of the quadriceps and protects the joint.","The largest sesamoid bone; cartilage on its back is the thickest in the body (~5 mm).",[("Width","≈ 5 cm"),("Cartilage thickness","≈ 4-5 mm")],"Babies are born with only a cartilage kneecap that ossifies around age 3-5.","8.4")
    B(f"tibia_fibula_{sd}",f"{sn} tibia and fibula (shin)",0.4,f"The {s2} lower-leg bones: weight-bearing tibia and slender fibula.","The big shin bone carries your weight and the thin outer bone mostly anchors muscles.","The tibia supports about 85-90% of load while the fibula forms the outer ankle.","Interosseous membrane transfers load; the tibial plateau articulates with femoral condyles via menisci.",[("Tibia length","≈ 36-40 cm")],"The fibula can be removed for bone grafts with little effect on walking.","8.4")
    B(f"foot_bones_{sd}",f"{sn} foot bones",0.26,f"The {s2} foot has 26 bones forming arches.","Your foot's arches work like springs: they absorb landing and push you forward.","7 tarsals, 5 metatarsals, 14 phalanges form medial longitudinal, lateral and transverse arches.","The plantar fascia and 'windlass mechanism' stiffen the foot during push-off; the calcaneus is the largest tarsal.",[("Bones","26"),("Foot length","≈ 25 cm")],"Humans have arched feet unlike any other ape.","8.4")
# bone structure
S.append(N("long_bone","Long bone (structure)","structure","anatomy",0.3,"A long bone has a hard outer shell, a spongy interior and a marrow cavity.","A long bone is hard on the outside, like a tube, and honeycombed at the ends, which keeps it strong yet light.","The shaft (diaphysis) is mostly compact bone around a marrow cavity; the ends (epiphyses) hold spongy bone and are capped with cartilage.","Compact bone is organized into osteons (Haversian systems); spongy bone is a lattice of trabeculae oriented along stress lines; the periosteum supplies osteoprogenitors; growth plates add length until closure.",[("Compact bone","≈ 80% of skeleton mass"),("Osteon diameter","≈ 0.2-0.3 mm")],"Bone is about as strong as cast iron for its weight in compression but much lighter.",par=["skeletal_system"],made=["bone_tissue"],refs=[("ANP","6.3")],kn=["musculoskeletal"],rel=["femur_r","humerus_r"]))
for i,t,sc,sm,b,d,e,at,lab,dy in [
("compact_bone","Compact bone",0.005,"Dense bone forming the outer shell.","The hard, smooth outer layer that gives bone its strength.","Built from cylinders called osteons with a central canal carrying vessels.","Lamellae of mineralized collagen surround Haversian canals, linked by Volkmann's canals; osteocytes in lacunae communicate via canaliculi.",(0.012,0.0,0.0),"Compact bone","Osteons are tiny: dozens fit in a pinhead cross-section."),
("spongy_bone","Spongy (cancellous) bone",0.02,"A lattice of thin struts at the bone ends.","A honeycomb inside the ends of bones that makes them light and shock-absorbing.","Trabeculae align along stress; marrow fills the gaps.","Higher surface-to-volume ratio gives it ~8× the remodeling turnover of cortical bone.",(0.0,0.13,0.0),"Spongy bone","Spongy bone is renewed far faster than compact bone."),
("bone_marrow","Bone marrow",0.03,"Soft tissue inside bones that makes blood cells.","Red marrow produces blood cells; yellow marrow stores fat.","Hematopoietic stem cells in marrow niches give rise to red cells, white cells and platelets.","Adults produce ≈ 2×10^11 red cells and ≈ 10^11 platelets and neutrophils daily; niches involve CXCL12-abundant reticular cells and osteoblasts.",(0.0,0.0,0.0),"Bone marrow","Your marrow makes about 2 million red blood cells every second."),
("periosteum","Periosteum",0.001,"A tough membrane covering the outer bone.","The skin of the bone: tough, full of nerves and blood vessels, and key to bone healing.","It supplies cells and blood to the bone and anchors tendons.","Inner cambium layer contains osteoprogenitors; Sharpey's fibres anchor tendons to bone; richly innervated, hence the pain of fractures.",(0.0,-0.05,0.0135),"Periosteum","Bone breaks hurt largely because the periosteum is packed with nerves."),
("growth_plate","Growth plate (epiphyseal plate)",0.01,"A cartilage disc that lets a growing bone lengthen.","Children grow taller because cartilage here keeps being made and then turned into bone.","Cells stack in columns, enlarge, die and are replaced by bone. It closes after puberty.","Zones: resting, proliferative, hypertrophic and calcification; regulated by GH/IGF-1, sex steroids, thyroid hormone, and Ihh/PTHrP.",(0.0,0.10,0.0),"Growth plate","Growth plates are the weakest part of a child's skeleton."),]:
    S.append(N(i,t,"structure","anatomy",sc,sm,b,d,e,[("Role",sm.rstrip('.'))],dy,par=["long_bone"],made=["bone_tissue"],hs=("long_bone",at,lab),refs=[("ANP","6.3")],kn=["musculoskeletal"]))
S.append(N("synovial_joint","Synovial joint",0.05,"A joint with a fluid-filled capsule that lets bones slide smoothly.","A freely movable joint, like your knee or shoulder, where slippery cartilage and fluid cut friction to almost nothing.","Cartilage caps the bones; a capsule makes synovial fluid; ligaments stabilize. Types include hinge, ball-and-socket, pivot, saddle.","Friction coefficients of ≈ 0.001-0.01 arise from boundary lubrication (lubricin, hyaluronan) and fluid-film mechanisms. Cartilage has no blood supply and is nourished by loading-driven diffusion.",[("Friction coefficient","≈ 0.001-0.01"),("Synovial fluid in knee","≈ 1-3 mL")],"Joint cartilage can be slipperier than ice on ice.","structure","anatomy",None) if False else N("synovial_joint","Synovial joint","structure","anatomy",0.05,"A joint with a fluid-filled capsule that lets bones slide smoothly.","A freely movable joint, like your knee or shoulder, where slippery cartilage and fluid cut friction to almost nothing.","Cartilage caps the bones, a capsule makes lubricating synovial fluid, and ligaments stabilize the joint. Types include hinge, ball-and-socket, pivot and saddle.","Friction coefficients of about 0.001-0.01 arise from boundary lubrication (lubricin, hyaluronan) and fluid-film mechanisms. Cartilage lacks blood vessels and is nourished by loading-driven diffusion.",[("Friction coefficient","≈ 0.001-0.01"),("Synovial fluid in knee","≈ 1-3 mL")],"Joint cartilage can be slipperier than ice on ice.",par=[SK],made=["cartilage_tissue","dense_connective_tissue"],refs=[("ANP","9.4")],kn=["musculoskeletal"]))
save("body_skeletal",S)
